package pt.ulusofona.cd.supplier.config;
import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.http.client.JdkClientHttpRequestFactory; import org.springframework.web.client.RestClient; import org.springframework.web.service.invoker.HttpServiceProxyFactory; import org.springframework.web.client.support.RestClientAdapter; import pt.ulusofona.cd.supplier.client.ProductClient; import java.net.http.HttpClient; import java.time.Duration;
@Configuration public class HttpClientConfig { @Bean ProductClient productClient(ServiceUrls urls){HttpClient hc=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();JdkClientHttpRequestFactory f=new JdkClientHttpRequestFactory(hc);f.setReadTimeout(Duration.ofSeconds(3));RestClient rc=RestClient.builder().baseUrl(urls.productBaseUrl()).requestFactory(f).build();return HttpServiceProxyFactory.builderFor(RestClientAdapter.create(rc)).build().createClient(ProductClient.class);} }
